'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{createHash,webcrypto}=require('node:crypto'),{JSDOM}=require('jsdom');
const read=n=>fs.readFileSync(path.join(__dirname,n),'utf8'),original=read('original-fine.js'),candidate=read('candidate-fine.js'),hash=s=>createHash('sha256').update(s).digest('hex');
const html='<main><!--original--><div class="example-card" id="r"><span id="a" class="card-chunk card-chunk-active sf-target-chunk" data-chunk-ids="1 2" data-chunk-sentence-ids="1">A😀 <mark class="target-word"><b data-chunk-ids="2">fine</b></mark></span><span id="b" class="card-chunk card-chunk-active sf-target-chunk" data-chunk-ids="1">whole</span><span id="c" class="card-chunk card-chunk-active" data-chunk-ids="3">other</span><i data-chunk-sentence-ids="bad" data-chunk-ids="5">malformed</i><details class="sf-ownership-history"><summary>audit</summary><span class="card-chunk" data-chunk-sentence-ids="9" data-chunk-ids="9">keep</span></details></div><div class="example-card" id="s"><span class="card-chunk" data-chunk-sentence-ids="4" data-chunk-ids="4 5">second</span></div></main>';
const bindings={module_sha256:hash(original),source_sha256:hash(html),metadata_sha256:hash('metadata-v1')};
function fixture(t,code=candidate,options={}){const dom=new JSDOM('<!doctype html><body>'+html+'</body>',{runScripts:'outside-only'});t.after(()=>dom.window.close());const w=dom.window;w.TextEncoder=TextEncoder;Object.defineProperty(w.crypto,'subtle',{value:options.digest||webcrypto.subtle});w.__ankiSlimManualRefresh=options.manual!==false;if(options.state!==false)w.__ankiCardChunkState={root:w.document.getElementById('r'),side:'en',ids:['1'],sentenceIds:['1']};w.eval(code);return{w,d:w.document,api:w.AnkiFineChunkRuntime};}
function snapshot(f,h){return{html:f.d.body.innerHTML,stats:JSON.parse(JSON.stringify(h.stats())),state:f.w.__ankiCardChunkState===null?'null':f.w.__ankiCardChunkState===undefined?'absent':'object'};}
function identities(f){const nodes=Array.from(f.d.querySelectorAll('*')),texts=nodes.map(n=>Array.from(n.childNodes));return()=>nodes.forEach((n,i)=>{assert.equal(n.isConnected,true);assert.deepEqual(Array.from(n.childNodes),texts[i]);});}
function build(t,options){const f=fixture(t,candidate,options),out=f.api.compile(f.d,bindings);return{...f,...out,pin:hash(out.serialized)};}
async function rejectedWithoutWrites(t,serialized,pin,modify,versions=bindings,options){const f=fixture(t);modify?.(f);const before=f.d.documentElement.outerHTML,state=f.w.__ankiCardChunkState,mo=new f.w.MutationObserver(()=>{});mo.observe(f.d.documentElement,{subtree:true,attributes:true,characterData:true,childList:true});await assert.rejects(f.api.hydrate(f.d,serialized,pin,versions,options));assert.equal(f.d.documentElement.outerHTML,before);assert.equal(f.w.__ankiCardChunkState,state);assert.equal(mo.takeRecords().length,0);mo.disconnect();const h=f.api.install(f.d);assert.ok(h,'rejection must not poison installed');}

test('RED control: original runtime has no compiled entry; exact ten-boundary inverse restores source',()=>{assert.equal(original.includes('compile: compileFine'),false);const edits=JSON.parse(read('edits.json'));let value=candidate;for(const [a,b]of edits.slice().reverse()){assert.equal(value.split(b).length,2);value=value.replace(b,a);}assert.equal(value,original);assert.equal(hash(value),bindings.module_sha256);});
test('compile runs actual install; hydrate binds original nodes and matches initial DOM IDs stats active reset and disposal',async t=>{const old=fixture(t,original),buildResult=build(t),runtime=fixture(t),identity=identities(runtime),a=old.api.install(old.d),b=await runtime.api.hydrate(runtime.d,buildResult.serialized,buildResult.pin,bindings);assert.deepEqual(snapshot(buildResult,buildResult.handle),snapshot(old,a));assert.deepEqual(snapshot(runtime,b),snapshot(old,a));assert.equal(runtime.d.getElementById('c').classList.contains('card-chunk-active'),false);assert.equal(runtime.w.__ankiCardChunkState,null);identity();a.dispose();b.dispose();buildResult.handle.dispose();assert.deepEqual(snapshot(runtime,b),snapshot(old,a));assert.deepEqual(snapshot(buildResult,buildResult.handle),snapshot(old,a));assert.equal(runtime.d.getElementById('c').classList.contains('card-chunk-active'),false,'do not restore active state the original does not restore');identity();});
test('all semantic work is build-side; hydrate preserves original refresh, late content and conditional external restoration',async t=>{const built=build(t),old=fixture(t,original),next=fixture(t),a=old.api.install(old.d);let analyses=0;const q=next.d.querySelectorAll.bind(next.d);next.d.querySelectorAll=s=>{if(s==='.example-card')analyses++;return q(s);};const b=await next.api.hydrate(next.d,built.serialized,built.pin,bindings);assert.equal(analyses,0);for(const f of [old,next]){const n=f.d.getElementById('a');n.setAttribute('data-chunk-ids','1 8');n.className='card-chunk sf-target-chunk external';f.d.getElementById('r').insertAdjacentHTML('beforeend','<span id="late" class="card-chunk" data-chunk-ids="1 7">late</span>');}a.refresh();b.refresh();assert.deepEqual(snapshot(next,b),snapshot(old,a));for(const f of [old,next]){f.d.getElementById('a').setAttribute('data-chunk-ids','external-ids');f.d.getElementById('a').className='foreign-later';}a.dispose();b.dispose();assert.deepEqual(snapshot(next,b),snapshot(old,a));assert.equal(next.d.getElementById('a').getAttribute('data-chunk-ids'),'external-ids');assert.equal(next.d.getElementById('a').className,'foreign-later');});
test('after tampering cannot update its own external anchor; every rejection precedes target writes',async t=>{const built=build(t),plan=JSON.parse(built.serialized);plan.operations.find(o=>o.kind==='ids').value='1';await rejectedWithoutWrites(t,JSON.stringify(plan),built.pin);await rejectedWithoutWrites(t,built.serialized,'0'.repeat(64));});
test('missing duplicate misplaced plan entries and incomplete operations reject even structurally authenticated malformed artifacts',async t=>{const built=build(t);const changes=[p=>p.before.pop(),p=>p.before.push(p.before[0]),p=>p.records.push({...p.records[0]}),p=>{p.records[0].path='999';},p=>p.operations.splice(p.operations.findIndex(o=>o.kind==='ids'),1),p=>p.records.pop(),p=>{p.schema='unknown';}];for(const change of changes){const p=JSON.parse(built.serialized);change(p);const raw=JSON.stringify(p);await rejectedWithoutWrites(t,raw,hash(raw));}});
test('changed semantic attribute/member order and all version bindings reject without writes',async t=>{const built=build(t);for(const change of [f=>f.d.getElementById('a').setAttribute('data-chunk-ids','1 99'),f=>{const r=f.d.getElementById('r');r.insertBefore(f.d.getElementById('c'),f.d.getElementById('a'));},f=>{const n=f.d.createElement('span');n.setAttribute('data-chunk-ids','99');f.d.getElementById('r').append(n);}])await rejectedWithoutWrites(t,built.serialized,built.pin,change);for(const key of Object.keys(bindings))await rejectedWithoutWrites(t,built.serialized,built.pin,null,{...bindings,[key]:'f'.repeat(64)});});
test('digest-pending cancellation and changed live state never write or seed the real installed map',async t=>{const built=build(t);let finish;const digest={digest(...args){return new Promise(resolve=>{finish=()=>Reflect.apply(webcrypto.subtle.digest,webcrypto.subtle,args).then(resolve);});}};const f=fixture(t,candidate,{digest}),before=f.d.documentElement.outerHTML;let current=true;const task=f.api.hydrate(f.d,built.serialized,built.pin,bindings,{isCurrent:()=>current});current=false;await finish();await assert.rejects(task,/cancelled/);assert.equal(f.d.documentElement.outerHTML,before);assert.ok(f.api.install(f.d));await rejectedWithoutWrites(t,built.serialized,built.pin,g=>{g.w.__ankiCardChunkState.ids=['2'];});});
test('original automatic observer and idempotent dispose remain live after hydration',async t=>{const built=build(t,{manual:false}),old=fixture(t,original,{manual:false}),next=fixture(t,candidate,{manual:false}),a=old.api.install(old.d),b=await next.api.hydrate(next.d,built.serialized,built.pin,bindings);for(const f of [old,next])f.d.getElementById('r').insertAdjacentHTML('beforeend','<span id="late-observed" class="card-chunk" data-chunk-ids="1 8">late</span>');await new Promise(r=>setTimeout(r,25));assert.deepEqual(snapshot(next,b),snapshot(old,a));a.dispose();b.dispose();a.dispose();b.dispose();assert.deepEqual(snapshot(next,b),snapshot(old,a));});

test('Fine-irrelevant Text, countdown, base, child frame state and decorative attributes are ignored and preserved',async t=>{
 const built=build(t),old=fixture(t,original),next=fixture(t);for(const f of [old,next]){f.d.getElementById('c').firstChild.data='changed side text';f.d.getElementById('r').append(f.d.createTextNode('new text'));f.d.getElementById('r').setAttribute('data-decorative','changed');const base=f.d.createElement('base');base.href='https://example.test/final/';f.d.head.append(base);const wrapper=f.d.createElement('section');wrapper.className='anki-countdown-content';const main=f.d.querySelector('main');main.replaceWith(wrapper);wrapper.append(main);const footer=f.d.createElement('p');footer.className='exam-countdown';footer.textContent='changing countdown';wrapper.append(footer);const child=f.d.createElement('iframe');child.dataset.studyChildToken='updated';child.style.height='1413px';wrapper.append(child);}
 const beforeNodes=identities(next),a=old.api.install(old.d),b=await next.api.hydrate(next.d,built.serialized,built.pin,bindings);assert.deepEqual(snapshot(next,b),snapshot(old,a));beforeNodes();a.refresh();b.refresh();assert.deepEqual(snapshot(next,b),snapshot(old,a));a.dispose();b.dispose();assert.deepEqual(snapshot(next,b),snapshot(old,a));beforeNodes();assert.ok(next.d.body.textContent.includes('changed side text'));assert.ok(next.d.body.textContent.includes('changing countdown'));});
test('new or removed members, history and mark ancestry or selector-type changes reject before any write',async t=>{
 const built=build(t);for(const change of [f=>{f.d.getElementById('b').remove();},f=>{f.d.getElementById('a').classList.add('sf-ownership-history');},f=>{f.d.getElementById('r').classList.remove('example-card');},f=>{f.d.getElementById('c').setAttribute('data-chunk-sentence-ids','3');},f=>{const wrap=f.d.createElement('div');wrap.className='sf-ownership-authority';const a=f.d.getElementById('a');a.replaceWith(wrap);wrap.append(a);},f=>{const mark=f.d.querySelector('mark.target-word');f.d.getElementById('c').append(mark);},f=>{f.d.querySelector('mark.target-word').classList.remove('target-word');},f=>{f.d.querySelector('[data-native-ownership-history]')?.removeAttribute('data-native-ownership-history');const marker=f.d.createElement('aside');marker.setAttribute('data-native-ownership-history','yes');f.d.getElementById('r').prepend(marker);}])await rejectedWithoutWrites(t,built.serialized,built.pin,change);
});
test('versions are synchronously copied before digest: caller mutations cannot change the authenticated expectation',async t=>{
 const built=build(t);let finish;const delayed={digest(...args){return new Promise(resolve=>{finish=()=>Reflect.apply(webcrypto.subtle.digest,webcrypto.subtle,args).then(resolve);});}};
 const good=fixture(t,candidate,{digest:delayed}),values={...bindings},task=good.api.hydrate(good.d,built.serialized,built.pin,values);values.source_sha256='f'.repeat(64);await finish();const h=await task;assert.equal(h.stats().filteredSpans,built.handle.stats().filteredSpans);
 const bad=fixture(t,candidate,{digest:delayed}),changed={...bindings,metadata_sha256:'e'.repeat(64)},before=bad.d.documentElement.outerHTML,pending=bad.api.hydrate(bad.d,built.serialized,built.pin,changed);changed.metadata_sha256=bindings.metadata_sha256;await finish();await assert.rejects(pending,/version/);assert.equal(bad.d.documentElement.outerHTML,before);assert.ok(bad.api.install(bad.d));
});
test('hydrate uses exactly one full semantic member query, no Text proof, and still composes with both whole-probe guards',async t=>{
 const built=build(t),p=JSON.parse(built.serialized);assert.ok(!built.serialized.includes('A😀'));assert.ok(p.before.every(entry=>entry[1]===1&&entry[5]===null));assert.ok(p.after.every(entry=>entry.length===2));const f=fixture(t),query=f.d.querySelectorAll.bind(f.d),calls=[];f.d.querySelectorAll=selector=>{calls.push(selector);return query(selector);};await f.api.hydrate(f.d,built.serialized,built.pin,bindings);assert.equal(calls.length,1);assert.ok(calls[0].startsWith('.example-card,[data-chunk-ids],[data-chunk-sentence-ids],mark.target-word,'));
 const adapter=new Function(read('fine-whole-adapter.js')+';return adaptNativeFineWholeProbe;')();for(const pin of ['5c361607267287f859150ac4f7716d05b94a6ee5bebc0478d11660e947b6a15e','be39224f5f2d47eee8cad80060aeb364e72448b5cd1c11a7f7c8fd8d999e1b93']){const code=adapter(candidate,pin);let inverseOrder=adapter(original,pin);for(const [before,after]of JSON.parse(read('edits.json'))){assert.equal(inverseOrder.split(before).length,2);inverseOrder=inverseOrder.replace(before,after);}assert.equal(inverseOrder,code);assert.ok(code.includes("chunks = Array.from(root.querySelectorAll('[data-chunk-ids],[data-chunk-sentence-ids]'))"));const item=fixture(t,code),out=item.api.compile(item.d,bindings);assert.equal(out.serialized,built.serialized);}
});

function compileWithState(t,state){const f=fixture(t,candidate,{state:false});if(state!==undefined)f.w.__ankiCardChunkState=state;const built=f.api.compile(f.d,bindings);return{...built,pin:hash(built.serialized)};}
async function inheritedRejectThenOriginalWorks(t,built,configure){const f=fixture(t,candidate,{state:false});configure(f);const state=f.w.__ankiCardChunkState,before=f.d.documentElement.outerHTML,owned=Object.prototype.hasOwnProperty.call(f.w,'__ankiCardChunkState'),mo=new f.w.MutationObserver(()=>{});mo.observe(f.d.documentElement,{subtree:true,attributes:true,characterData:true,childList:true});let accepted=false,error;try{await f.api.hydrate(f.d,built.serialized,built.pin,bindings);accepted=true;}catch(value){error=value;}
assert.equal(accepted,false,'v2 accepted hidden inherited consumer state; activeC='+f.d.getElementById('c').classList.contains('card-chunk-active')+' owned='+Object.prototype.hasOwnProperty.call(f.w,'__ankiCardChunkState'));assert.ok(error);assert.equal(f.d.documentElement.outerHTML,before);assert.equal(f.w.__ankiCardChunkState,state);assert.equal(Object.prototype.hasOwnProperty.call(f.w,'__ankiCardChunkState'),owned);assert.equal(mo.takeRecords().length,0);mo.disconnect();const h=f.api.install(f.d);assert.equal(f.w.__ankiCardChunkState,null);assert.equal(Object.prototype.hasOwnProperty.call(f.w,'__ankiCardChunkState'),true);assert.equal(f.d.getElementById('a').classList.contains('card-chunk-active'),false);assert.equal(f.d.getElementById('c').classList.contains('card-chunk-active'),false);assert.ok(h);}
test('inherited Window data state cannot masquerade as absent; reject before writes and leave ordinary install usable',async t=>{const built=compileWithState(t);await inheritedRejectThenOriginalWorks(t,built,f=>{const state={root:f.d.getElementById('r'),side:'en',ids:['1'],sentenceIds:['1']};Object.defineProperty(Object.getPrototypeOf(f.w),'__ankiCardChunkState',{configurable:true,writable:true,value:state});assert.equal(f.w.__ankiCardChunkState,state);assert.equal(Object.prototype.hasOwnProperty.call(f.w,'__ankiCardChunkState'),false);});});
test('inherited state consumer fields cannot masquerade as absent; non-enumerable own consumers also fail closed',async t=>{const built=compileWithState(t,{});await inheritedRejectThenOriginalWorks(t,built,f=>{f.w.__ankiCardChunkState=Object.create({root:f.d.getElementById('r'),side:'en',ids:['1'],sentenceIds:['1']});assert.deepEqual(Object.keys(f.w.__ankiCardChunkState),[]);});await inheritedRejectThenOriginalWorks(t,built,f=>{const state={};for(const [key,value]of Object.entries({root:f.d.getElementById('r'),side:'en',ids:['1'],sentenceIds:['1']}))Object.defineProperty(state,key,{value,writable:true,configurable:true});f.w.__ankiCardChunkState=state;assert.deepEqual(Object.keys(state),[]);});});
